    (3::int, 3704::int, 3704::int, 'DEALERS, SOCIEDAD ANONIMA'::text, null::text, '104225513'::text, '104225513'::text, null::text, null::text, '5 CALLE 1-25 Z9, GUATEMALA'::text, null::text, null::text, 1::int, 'S'::text, false::boolean, 'A'::text, 'LED IT'::text, 'LED IT'::text, null::int, false::boolean, null::int, null::text, null::timestamp, null::text, 3::int, null::int, null::text, 0::int, true::boolean, null::text, 1::int, false::boolean, 'DEALERS, SOCIEDAD ANONIMA'::text),
